-- ── Sanity check (read-only; raises rather than reporting a silent partial) ───
-- Scoped to the roll calls THIS migration writes. Other passes have legitimately
-- ingested 117th/118th votes from a wider roster (H.R. 82 carries 44), and counting
-- those here would fail the deploy on data that is not this migration's to police.
DO $$
DECLARE
  roll_ids integer[];
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
BEGIN
  SELECT array_agg(r.id) INTO roll_ids
    FROM vr_rollcalls r
    JOIN (VALUES
      ('senate'::text, 117::integer, 1::integer, 110::integer),
      ('house', 117, 1, 72),
      ('senate', 117, 1, 314),
      ('house', 117, 1, 369),
      ('house', 117, 1, 405),
      ('senate', 117, 1, 499),
      ('house', 117, 2, 38),
      ('senate', 117, 2, 71),
      ('senate', 117, 2, 242),
      ('house', 117, 2, 299),
      ('house', 117, 2, 309),
      ('senate', 117, 2, 271),
      ('house', 117, 2, 404),
      ('senate', 117, 2, 280),
      ('senate', 117, 2, 325),
      ('house', 117, 2, 420),
      ('senate', 117, 2, 362),
      ('house', 117, 2, 513),
      ('senate', 117, 2, 396),
      ('house', 118, 1, 243),
      ('senate', 118, 1, 146),
      ('senate', 118, 1, 343),
      ('house', 118, 1, 723),
      ('house', 118, 2, 119),
      ('senate', 118, 2, 150),
      ('house', 118, 2, 151),
      ('senate', 118, 2, 154),
      ('house', 118, 2, 500),
      ('senate', 118, 2, 325)
    ) AS ingested(chamber, congress, session, roll_number)
      ON ingested.chamber = r.chamber AND ingested.congress = r.congress
     AND ingested.session = r.session AND ingested.roll_number = r.roll_number;
  n_rolls := coalesce(array_length(roll_ids, 1), 0);
  SELECT count(*) INTO n_votes FROM vr_member_votes WHERE rollcall_id = ANY(roll_ids);
  -- A member vote on one of THESE roll calls whose politician_id is not a roster slug
  -- would mean something other than this migration wrote it, or that the roster moved
  -- underneath us. Either way the attribution can no longer be trusted.
  SELECT count(*) INTO n_orphan
    FROM vr_member_votes mv
   WHERE mv.rollcall_id = ANY(roll_ids)
     AND mv.politician_id NOT IN (
       'aoc', 'barrasso', 'bennie_thompson', 'boebert', 'booker', 'bruce_westerman', 'collins', 'crockett', 'cruz', 'cstewart', 'curtis', 'don_davis', 'durbin', 'emmer', 'ernst', 'fetterman', 'frank_lucas', 'french_hill', 'gaetz', 'graham', 'grassley', 'hawley', 'jason_smith', 'jayapal', 'jim_jordan', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'kclark', 'khanna', 'lee', 'mariannette_miller_meeks', 'massie', 'maxine_waters', 'michael_guest', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_simpson', 'mtg', 'murkowski', 'owens', 'rand_paul', 'rick_crawford', 'rubio', 'scalise', 'schiff', 'scott_perry', 'stephanie_bice', 'steve_womack', 'tlaib', 'tom_cole', 'trent_kelly', 'warren', 'zeldin'
     );
  RAISE NOTICE 'Phase A votes: % of this ingest''s roll calls present, carrying % member votes', n_rolls, n_votes;
  IF n_rolls <> 29 THEN
    RAISE EXCEPTION 'Phase A votes: expected this ingest''s 29 roll calls to be present, found %', n_rolls;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Phase A votes: % member vote(s) on this ingest''s roll calls carry a politician_id outside the ingest roster', n_orphan;
  END IF;
END $$;
